56	```ts
57	type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue }
58	
59	interface ToolArgsMap {
60	  /** Ask the user a concise question when you need confirmation, a choice, or missing information before proceeding. Send one or more questions, each with a stable id that will be echoed in the answer. */
61	  ask_user_question: {
62	    /** Questions to ask the user before continuing. */
63	    questions: ({
64	      /** Stable id for this question; echoed in the answer. */
65	      id: string;
66	      /** The specific question to ask the user. */
67	      question: string;
68	      /** Optional short heading for the question, such as "Confirm" or "Choose Mode". */
69	      header?: string;
70	      /** Optional choices to show the user. If you recommend one, put it first and append "(Recommended)" to that label. */
71	      options?: ({
72	        /** Short user-facing option label. */
73	        label: string;
74	        /** One sentence explaining the tradeoff or impact. */
75	        description?: string;
76	      } & Record<string, JsonValue>)[];
77	      /** Whether the user may select more than one option. Defaults to false. */
78	      multi_select?: boolean;
79	    } & Record<string, JsonValue>)[];
80	  } & Record<string, JsonValue>;
81	  /** Execute a bash command (`bash -c`) and return its stdout/stderr. Each call runs in a fresh shell: no state (cwd, variables, functions) persists between calls — pass `workdir` instead of using `cd`. Non-zero exits are reported as `[exit code: N]`. Current harness environment facts are exposed through managed `$DSH_*` variables; inspect them when needed. Commands may run under a file sandbox; a blocked file operation is reported as `[sandbox: file access denied under <mode> mode]` — a policy denial, not a bug in the command; do not retry another way. Long output is truncated to its tail; the full output is saved to a file whose path is reported when available. Set `run_in_background: true` for long-running commands: the call returns a job id immediately; read its output with `job_output` and stop it with `job_kill`. Attempting a command the sandbox may deny is safe and expected: run it and read the marker rather than assuming the denial. When a command is denied and a wider mode would let it succeed, escalate immediately in the same turn — the one sanctioned exception to a denial: retry the exact same command once with `sandbox_permissions` (the narrowest wider mode that suffices) plus a one-sentence `justification`. Do not detour through chat to ask permission first — the approval prompt raised by that retry is how the user consents. If the session states approval prompts are disabled, there is no exception: a denial is final — do not set `sandbox_permissions`. Never escalate speculatively: ground the request in a real denial — normally the one this command just hit; escalating up front is fine only when this session already denied the same access. A rejected escalation is final for that command — stop and explain, never work around it — but it does not forbid attempting or escalating other commands later. */
82	  bash: {
83	    /** The bash command to execute. */
84	    command: string;
85	    /** Clear, concise description of what this command does in active voice, 5-10 words (shown in the UI). Examples: "ls" → "List files in current directory"; "git status" → "Show working tree status"; "npm install" → "Install package dependencies". */
86	    description: string;
87	    /** Timeout in milliseconds. The executor applies its configured default and cap, and kills the command on expiry. */
88	    timeoutMs?: number;
89	    /** Working directory for this command. Defaults to the session workspace; a relative path is resolved against it. */
90	    workdir?: string;
91	    /** Run in the background and return a job id immediately (collect with job_output, stop with job_kill). No timeout applies. */
92	    run_in_background?: boolean;
93	    /** The wider sandbox mode this command needs. Only valid as a one-shot retry of a command the sandbox just denied; requires justification and user approval. */
94	    sandbox_permissions?: "workspace-write" | "danger-full-access";
95	    /** Required with sandbox_permissions: one sentence for the user explaining why this exact command needs the wider access. */
96	    justification?: string;
97	  } & Record<string, JsonValue>;
98	  /** Create one persisted same-session completion goal when the current direct human request is a long-running objective that should continue across autonomous goal rounds. You may infer that intent without requiring the user to say "create a goal". Do not use this for trivial single-turn work. Execution rejects non-human and subagent authority. */
99	  create_goal: {
100	    /** The concrete completion objective inferred from the direct human request. */
101	    objective: string;
102	    /** Optional positive safe-integer limit on automatic continuation rounds. */
103	    max_goal_rounds?: number;
104	  } & Record<string, JsonValue>;
105	  /** Edit an existing UTF-8 text file by replacing literal text. */
106	  edit: {
107	    /** Path to edit, resolved by the filesystem backend. */
108	    file_path: string;
109	    /** Literal text to replace. Must match exactly. */
110	    old_string: string;
111	    /** Literal replacement text. Use an empty string to delete the match. */
112	    new_string: string;
113	    /** Replace all matches. Defaults to false; when false, old_string must appear exactly once. */
114	    replace_all?: boolean;
115	    /** The wider sandbox mode this file operation needs. Only valid as a one-shot retry of an operation the sandbox just denied; requires justification and user approval. */
116	    sandbox_permissions?: "workspace-write" | "danger-full-access";
117	    /** Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access. */
118	    justification?: string;
119	  } & Record<string, JsonValue>;
120	  /** Use only in plan mode. Present your plan for the user's review and, on approval, leave plan mode. Send the COMPLETE plan as markdown, starting with a # heading that names it. The user may approve (carry out the plan from your next step) or keep planning — their feedback comes back in the tool result; revise and present again. */
121	  exit_plan_mode: {
122	    /** The complete plan, as markdown, starting with a # heading that names it. */
123	    plan: string;
124	  } & Record<string, JsonValue>;
125	  /** Read the current same-session goal, including its exact id/revision, objective, phase, completed continuation rounds, round limit, blocker reason when present, and whether another continuation is armed. Call this before updating a goal. */
126	  get_goal: Record<string, JsonValue>;
127	  /** Find files whose paths match a glob pattern. Returns matching file paths — never directories — including hidden and ignored files (VCS metadata directories are excluded). Up to 100 paths come back in modification-time order; a larger result returns the first 100 paths in modification-time order, says so, and reports where the complete sorted list was saved. This tool does not enumerate directory entries. */
128	  glob: {
129	    /** Glob pattern to match file paths against (e.g. "**\/*.ts", "src/**\/*.test.js"). A pattern with no "/" matches the basename at any depth, so "*" and "*.ts" both search the whole tree; include a separator to anchor the depth. */
130	    pattern: string;
131	    /** Directory to search in. Defaults to the session workspace; a relative path resolves against it. */
132	    path?: string;
133	  } & Record<string, JsonValue>;
134	  /** Search file contents with a ripgrep regular expression. Returns matching lines with line numbers, grouped by file. Returns the first 250 matches inline; a capped result reports where the complete match list was saved. Use read on a matched file for surrounding context. */
135	  grep: {
136	    /** Regular expression to search for (ripgrep syntax). */
137	    pattern: string;
138	    /** File or directory to search. Defaults to the session workspace; a relative path resolves against it. */
139	    path?: string;
140	    /** One glob filter for which files to search (e.g. "*.ts", "*.{js,jsx}"). Not a list; negation is not supported. */
141	    include?: string;
142	  } & Record<string, JsonValue>;
143	  /** Request cancellation of a background agent's current turn by its agent id. The target may be your direct child or a deeper agent created under you. Only the current turn stops: messages already queued for the agent stay parked until a later send_message, agents it started keep running, and the agent itself stays available for follow-ups. This call returns as soon as the stop request is accepted, so the target may keep running briefly; interrupting an agent that already finished is an accepted no-op. */
144	  interrupt_agent: {
145	    /** The agent id of the running agent to interrupt. */
146	    agent_id: string;
147	  } & Record<string, JsonValue>;
148	  /** Request cancellation of a running background job by job id. Returns immediately; the job settles as killed once its work actually stops. */
149	  job_kill: {
150	    /** Job id returned by the tool that started the background work. */
151	    job_id: string;
152	    /** Optional short reason, recorded in the log and forwarded to the job. */
153	    reason?: string;
154	  } & Record<string, JsonValue>;
155	  /** List your background jobs (running and finished) with their ids, kinds, and statuses. */
156	  job_list: Record<string, JsonValue>;
157	  /** Read a background job. Stream jobs return only output since the previous read; final-output jobs return their result after settlement. Every response ends with `[status: ...]`. Reads are non-blocking unless `wait: true`, which waits up to the configured cap. */
158	  job_output: {
159	    /** Job id returned by the tool that started the background work. */
160	    job_id: string;
161	    /** Block until the job reaches a terminal status or the timeout expires. A timed-out wait returns [status: running] and leaves the job alive. */
162	    wait?: boolean;
163	    /** Max wait in milliseconds (only meaningful with wait: true). Defaults to the configured wait timeout; capped by the configured maximum. */
164	    timeout_ms?: number;
165	  } & Record<string, JsonValue>;
166	  /** List your continuable background subagents by durable id and label. Use it to recall which ones you started, not to poll for completion — you are told when one finishes. Status comes from the live registry: running means the agent is working right now, idle means it is loaded but between turns (it may be waiting on agents it started), and ready means it exists only in storage — resumable, not terminal, and not a result waiting to be collected; a `send_message` starts a new turn on the same conversation, and a direct child remains a `send_message` candidate in every status. The snapshot is not a delivery promise — `send_message` performs the authoritative check and may still fail. Children that could not be read are reported as diagnostics instead of being silently dropped. Scope `descendants` walks the whole tree below you in stable pre-order, annotating each entry with its durable direct-parent session id and depth. You may use `send_message` only for depth-1 entries; deeper entries are candidates for `interrupt_agent` only. */
167	  list_agents: {
168	    /** children (default) lists direct children only; descendants walks the complete tree below you. */
169	    scope?: "children" | "descendants";
170	  } & Record<string, JsonValue>;
171	  /** Run a foreground fresh-agent Ralph loop toward one immutable objective. Use only when the direct human explicitly asks for Ralph or fresh-agent iteration. Each round opens a new child with no parent conversation or prior child session; the shared workspace is long-term memory, and only a bounded structured report crosses rounds. The call returns when a worker reports completion or a concrete blocker, or at the round limit. Ordinary long-running same-session work belongs to goal tools. */
172	  ralph: {
173	    /** The immutable completion objective for every fresh Ralph round. */
174	    objective: string;
175	    /** Optional positive safe-integer round cap, bounded by the deployment ceiling. */
176	    maxRounds?: number;
177	  } & Record<string, JsonValue>;
178	  /** Read a UTF-8 text file and return line-numbered content. */
179	  read: {
180	    /** Path to read, resolved by the filesystem backend. */
181	    file_path: string;
182	    /** 1-based first line to return. Defaults to 1. */
183	    offset?: number;
184	    /** Maximum number of lines to return. Defaults to 2000. */
185	    limit?: number;
186	  } & Record<string, JsonValue>;
187	  /** Read a PNG/JPEG/WebP/GIF file and return the image itself. A path without a file extension is accepted; the format is detected from the file content, so normalized attachment paths can be passed directly without copying or renaming. Harness validates and downscales large supported images before the next model request, so use this tool directly instead of installing image libraries or creating thumbnails merely to inspect an image. Independent files may be read concurrently in small batches. Requires the current model to accept image input. */
188	  read_image: {
189	    /** Path to the image file, resolved by the filesystem backend. */
190	    file_path: string;
191	  } & Record<string, JsonValue>;
192	  /** Send a message to a background subagent by its subagent id, continuing the same conversation. It becomes the subagent's next turn: if it is still working, the message waits until its current turn finishes, so it cannot redirect work already underway. This call returns no answer from the subagent — only confirmation that the message was delivered — so use it to give it more work. A failure means the message was NOT delivered. */
193	  send_message: {
194	    /** The subagent id returned when the background subagent was started. */
195	    subagent_id: string;
196	    /** The message to deliver to the subagent. */
197	    message: string;
198	  } & Record<string, JsonValue>;
199	  /** Load the full instructions for an available skill. Call this with the exact skill name from the session skill catalog before acting on a task that names or clearly matches that skill. */
200	  skill: {
201	    /** The exact skill name from the available skills list. */
202	    name: string;
203	  } & Record<string, JsonValue>;
204	  /** Delegate a self-contained task to a subagent (a separate agent that works in its own context) to offload focused, independent work — research, a scoped implementation, an analysis — so it does not consume this conversation's context. The subagent returns its result, not its intermediate steps. Give it a complete, standalone prompt: it does not see this conversation. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result. */
205	  subagent: {
206	    /** A short (3-5 word) description of the delegated task, for display. */
207	    description: string;
208	    /** The complete, self-contained task for the subagent. It does not share this conversation's context, so include everything it needs. */
209	    prompt: string;
210	    /** Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it. */
211	    run_in_background?: boolean;
212	  } & Record<string, JsonValue>;
213	  /** Delegate a task to a subagent that inherits this conversation: a child agent seeded with all completed turns so far (it does not see the current in-flight turn). Use this when the subtask builds on this conversation's context — a follow-up analysis, a review, a continuation — without consuming this conversation's context for the work itself. You receive its result, not its intermediate steps. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result. */
214	  subagent_fork: {
215	    /** A short (3-5 word) description of the delegated task, for display. */
216	    description: string;
217	    /** The task for the subagent. It already sees this conversation's completed turns, so build on them freely and state only what is new. */
218	    prompt: string;
219	    /** Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it. */
220	    run_in_background?: boolean;
221	  } & Record<string, JsonValue>;
222	  /** Record and update a structured task list for the current work. Send the ENTIRE list every call — it REPLACES the previous list (there are no partial updates, no per-item edits). Use it to plan multi-step work and show progress: add one todo per concrete step before you start. Mark every todo being actively worked on `in_progress` — several at once when work genuinely runs in parallel (e.g. concurrent subagents or background commands), one for sequential work; while work remains, at least one task should be `in_progress`. Mark a todo `completed` the moment it is done (do not batch completions), and allow no `in_progress` item only once all work is complete. Skip the list for trivial single-step tasks. Statuses: `pending` (not started), `in_progress` (being worked on now), `completed` (finished). */
223	  todo_write: {
224	    /** The COMPLETE task list, replacing any previous list. */
225	    todos: ({
226	      /** What the task is — a short imperative line. */
227	      content: string;
228	      /** pending (not started) | in_progress (now) | completed (done). */
229	      status: "pending" | "in_progress" | "completed";
230	    })[];
231	  } & Record<string, JsonValue>;
232	  /** Update the exact current goal revision. edit, pause, and resume require a direct top-level human request. During an automatic continuation of the current goal, complete and blocked are also allowed. blocked is rejected before the configured minimum round count; the model remains responsible for judging that the same condition persisted across those rounds and must explain it in blocked_reason. */
233	  update_goal: {
234	    /** Exact id returned by get_goal. */
235	    goal_id: string;
236	    /** Exact positive revision returned by get_goal. */
237	    revision: number;
238	    /** edit | pause | resume | complete | blocked */
239	    action: "edit" | "pause" | "resume" | "complete" | "blocked";
240	    /** Replacement objective; valid only with action edit. */
241	    objective?: string;
242	    /** Replacement cap; valid only with action edit. */
243	    max_goal_rounds?: number;
244	    /** Concrete blocking condition; required only with action blocked. */
245	    blocked_reason?: string;
246	  } & Record<string, JsonValue>;
247	  /** Fetch the content of a specific HTTP(S) URL and return it decoded to text. */
248	  web_fetch: {
249	    /** The HTTP(S) URL to fetch. */
250	    url: string;
251	  } & Record<string, JsonValue>;
252	  /** Search the web for current information. Provide 1–4 queries in the required queries array. Returns an optional summary answer and a list of source URLs. */
253	  web_search: {
254	    /** Required search queries; accepts 1–4 items and merges their results. */
255	    queries: string[];
256	  } & Record<string, JsonValue>;
257	  /** Run a JavaScript workflow script that orchestrates subagents at scale. Use this for work that fans out across many independent pieces — an audit over many files, a migration, multi-angle research, adversarial verification of findings — where you write the orchestration as a script instead of delegating turn by turn. The workflow's identity rides the `meta` parameter as JSON: required `name` (short kebab-case) and `description` strings, optional `whenToUse` string and `phases` array (`{title, detail?, provider?, model?}`). The `script` parameter is the plain JavaScript body ONLY (NOT TypeScript, and NO `export const meta` statement — meta is a parameter, not code), running with top-level await; end with `return <value>` — the value must be JSON-serializable and is this tool's result. Script-body hooks: - `agent(prompt, opts?): Promise<any>` — run one subagent to completion. Without `opts.schema` it resolves to the child's final text; with `opts.schema` (an object-rooted JSON Schema using ONLY type/properties/required/additionalProperties/items/enum/const/oneOf — no pattern/format/numeric bounds) it resolves to the validated object. Resolves `null` when the child fails (filter with `.filter(Boolean)`). Other opts: `label` (display), `phase` (progress group), and independent `provider`/`model` LLM target overrides (either may be provided alone). Anything else (`effort`/`isolation`/`agentType`) is rejected loudly. - `pipeline(items, ...stages): Promise<any[]>` — run each item through the stages independently with NO barrier between stages (prefer this for multi-stage work). Each stage receives `(prev, item, index)`. An ordinary stage throw drops that ITEM to `null` and skips its remaining stages. - `parallel(thunks): Promise<any[]>` — run zero-argument functions concurrently and await ALL of them (a barrier; use only when a stage genuinely needs every prior result together). A throwing thunk resolves to `null`. - `phase(title)` — start a progress phase; `log(message)` — narrate progress; `args` — the tool call's `args` input, verbatim. Misused hooks (bad arguments, unknown options, unsupported schemas, tripped caps) throw errors that ALWAYS kill the script — they never dissolve into a per-item `null`. Constraints: concurrency and total-agent caps apply; no filesystem, network, timers, or Node.js APIs are provided — the agents do the work, the script only coordinates them. The run executes in the foreground: this call returns when the whole script finishes. */
258	  workflow: {
259	    /** The plain-JS workflow script body (top-level await allowed; NO `export const meta` statement; end with `return <json-value>`). */
260	    script: string;
261	    /** The workflow identity block (plain JSON — never code). */
262	    meta: {
263	      /** Short kebab-case workflow name. */
264	      name: string;
265	      /** One-line description of what the workflow does. */
266	      description: string;
267	      /** Optional guidance on when this workflow applies. */
268	      whenToUse?: string;
269	      /** Optional phase declarations matched by phase() calls. */
270	      phases?: ({
271	        /** The phase title phase() calls match by exact string. */
272	        title: string;
273	        /** Optional one-line description of the phase. */
274	        detail?: string;
275	        /** Optional provider override this phase is expected to use. */
276	        provider?: string;
277	        /** Optional model override this phase is expected to use. */
278	        model?: string;
279	      } & Record<string, JsonValue>)[];
280	    } & Record<string, JsonValue>;
